    sourceFigureViews.clear();
    openResponses.clear();
    openInputRevision++;
  };

  return {
    ensureRegistered,
    prepareOutlineValidation,
    clearOutlineValidation,
    resetTransientState,
    endAgentTurn,
    stopDelivery,
    captureOpenResponse,
    bindOpenResponseTurn,
    reviewQuestion,
    presentExam,
    submitExam,
  };
}

