// Throwaway reproduction: does lessonComplete after a preparation-change discard re-audit
// or return the generic "not approved yet" gap message?
import { createHash } from "node:crypto";
import { mkdirSync, mkdtempSync, statSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { pathToFileURL } from "node:url";
const extensionPath = "C:/Users/basam/.pi/agent/extensions/scholar/index.ts";
const { piPackageRoot, jitiPath, sdkAliases } = await import(pathToFileURL("C:/Users/basam/.pi/agent/extensions/scholar/tests/sdk.mjs").href);
const piRequire = createRequire(join(piPackageRoot, "package.json"));
const { createJiti } = await import(pathToFileURL(jitiPath).href);
const jiti = createJiti(import.meta.url, { moduleCache: false, alias: { ...sdkAliases,
  "@earendil-works/pi-coding-agent": join(piPackageRoot, "dist", "index.js"),
  "@earendil-works/pi-tui": piRequire.resolve("@earendil-works/pi-tui"),
  typebox: piRequire.resolve("typebox"),
} });
const loadModule = name => jiti.import(join(dirname(extensionPath), name));
const lesson = await loadModule("lesson.ts");
const { createScholarToolController } = await loadModule("tool-controller.ts");
const { ScholarRuntimeSession } = await loadModule("runtime-session.ts");

const root = mkdtempSync(join(tmpdir(), "scholar-repro-"));
const now = "2026-09-17T00:00:00.000Z";
const objective = "Explain how length and speed determine travel time";
const keyPoint = "At fixed speed, doubling the path length doubles travel time.";
const pdf = (() => {
  const stream = "BT /F1 11 Tf 60 750 Td 18 TL (1.1 Travel time) Tj T* (Travel time follows from the path length and the speed.) Tj ET";
  const objects = ["<< /Type /Catalog /Pages 2 0 R >>", "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>",
    `<< /Length ${Buffer.byteLength(stream)} >>\nstream\n${stream}\nendstream`,
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"];
  let out = "%PDF-1.4\n";
  const offsets = objects.map((object, index) => { const offset = Buffer.byteLength(out); out += `${index + 1} 0 obj\n${object}\nendobj\n`; return offset; });
  const xref = Buffer.byteLength(out);
  out += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n${offsets.map(offset => `${String(offset).padStart(10, "0")} 00000 n \n`).join("")}trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  return Buffer.from(out);
})();
const markdown = ["### Travel time from a constant speed",
  "A model connects an input to an observable result. Travel time follows from the path length and the speed.",
  "", "$$t = \\frac{d}{v}$$", ""].join("\n");
const libraryRoot = join(root, "library"), vault = join(root, "vault");
mkdirSync(libraryRoot, { recursive: true }); mkdirSync(vault, { recursive: true });
const sourcePath = join(libraryRoot, "travel-time.pdf");
writeFileSync(sourcePath, pdf);
const sha256 = createHash("sha256").update(pdf).digest("hex");
const section = { id: "s1", number: "1.1", title: "Travel time", order: 1, startPage: 1, endPage: 1,
  objectives: [objective], coveredObjectives: [], requiredChecks: ["conceptual"], objectiveChecks: [{ objective, checks: ["conceptual"] }],
  keyPoints: [keyPoint], misconceptions: [], status: "learning",
  synthesis: "Travel time follows from path length and speed.", transcript: [], attempts: [],
  figureCoverage: { pages: [{ page: 1, read: true, viewed: { width: 600, height: 800 }, candidates: [],
    review: { page: 1, observation: "The full source page contains text and no figures.", figures: [] } }] },
  learnQuality: { version: 1, coverage: [{ id: "time-concept", kind: "concept", description: "Explain the meaning of travel time",
    sourcePages: [1], objective, lessonId: "fixture-explanation", evidence: "A model connects an input to an observable result." }], reviews: [] },
  createdAt: now, updatedAt: now };
const book = { schemaVersion: 3, revision: 0, id: sha256, instanceId: "repro-discard",
  source: { absolutePath: sourcePath, relativePath: "travel-time.pdf", fileName: "travel-time.pdf", format: "pdf",
    fingerprint: { sha256, size: pdf.length, mtimeMs: statSync(sourcePath).mtimeMs } },
  metadata: { title: "Repro fixture", authors: [], pageCount: 1 }, outlineStatus: "ready",
  chapters: [{ id: "c1", number: "1", order: 1, title: "Motion", startPage: 1, endPage: 1, status: "learning", sections: [section] }],
  currentSectionId: "s1", exams: [], tutorSessions: [], noteDirectory: "Repro fixture", createdAt: now, updatedAt: now };
lesson.saveLesson(section, book, { id: "fixture-explanation", title: "Travel time from a constant speed", markdown, objectives: [objective],
  keyPoints: [keyPoint], sourcePages: [1] });

const session = new ScholarRuntimeSession();
session.activate(book.id, "learn", "s1");
let definition, nextCall = 0;
const controller = createScholarToolController({
  pi: { registerTool(tool) { definition = tool; } }, session,
  getConfig: () => ({ libraryRoot, obsidianRoot: vault }),
  loadBook: async () => book,
  mutateBook: async (_id, mutate) => ({ book, result: await mutate(book) }),
  isActiveAuthority: () => true, isSetupActive: () => false,
});
controller.ensureRegistered();
const requests = [], held = [];
const model = { id: "fixture", provider: "fixture", api: "fixture", input: ["text"], contextWindow: 100_000, maxTokens: 8000 };
const reply = verdict => ({ role: "assistant", api: model.api, provider: model.provider, model: model.id, stopReason: "stop", timestamp: Date.now(),
  content: [{ type: "text", text: JSON.stringify(verdict) }],
  usage: { input: 200, output: 40, cacheRead: 0, cacheWrite: 0, totalTokens: 240, cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } } });
let gate = "hold";
const context = { hasUI: false, ui: { notify: () => {} }, model, modelRegistry: { complete: async (_selected, reviewContext) => {
  const role = /Assigned role: (\w+)\./.exec(reviewContext.systemPrompt)?.[1] || "unknown";
  requests.push(role);
  if (gate === "hold") return new Promise(resolve => held.push({ role, resolve }));
  return reply({ status: "pass", findings: [] });
} } };
const textOf = result => result.content.map(item => item.type === "text" ? item.text : "").join("\n");

const saved = await controller.ensureRegistered ? null : null;
const save = await definition.execute("repro-1", { action: "notes", synthesis: "A recap addition that does not touch the explanation." }, undefined, undefined, context);
console.log("save tone:", save.details.tone, "| requests:", requests.length);
await new Promise(resolve => setTimeout(resolve, 30));
console.log("in-flight audits:", requests.length);

// Simulate reopening the same section: activateBook -> resetTransientState -> activate (new session state).
controller.resetTransientState();
session.activate(book.id, "learn", "s1");
for (const item of held.splice(0)) item.resolve(reply({ status: "pass", findings: [] })); // providers that ignore abort
await new Promise(resolve => setTimeout(resolve, 30));
const before = requests.length;
gate = "auto";
const complete = await definition.execute("repro-2", { action: "notes", lessonComplete: true }, undefined, undefined, context);
console.log("lessonComplete tone:", complete.details.tone);
console.log("new audit requests:", requests.length - before);
console.log("message:", textOf(complete).slice(0, 400));
console.log("committed:", Boolean(book.chapters[0].sections[0].lessonCommit), "| receipts:", section.learnQuality.reviews.map(r => [r.role, r.status, reception(r)]).map(String).join(" | "));
function reception(r) { return r.failure ? `failure:${r.failure.code}` : "ok"; }

