/** The evidence revision of every saved unit, keyed by entry: a save compares this before and
 * after to retire receipts that audited evidence the unit no longer cites. */
const evidenceRevisions = (section: ScholarSection, sourceHash: string) =>
  new Map(lessonReviewUnits(section, sourceHash).map(unit => [unit.entryId, unit.revision]));
const invalidateSupersededEvidence = (section: ScholarSection, before: Map<string, string>, sourceHash: string): void => {
