```ts
  /** Receipts retired by a save that changed a unit's audited evidence: they describe pages or
   * crops the unit no longer cites, so they must not approve its replacement. */
  const retireSupersededEvidence = (section: ScholarSection, before: Map<string, string>, sourceHash: string): void => {
    if (!section.learnQuality) return;
    const retired = new Set(lessonReviewUnits(section, sourceHash).filter(unit => {
      const evidence = before.get(unit.entryId);
      return evidence && evidence.split("\u0000")[0] === unit.contentHash && evidence.split("\u0000")[1] !== unit.revision;
    }).map(unit => unit.contentHash));
    if (retired.size) section.learnQuality.reviews = section.learnQuality.reviews.filter(receipt => !retired.has(receipt.contentHash));
  };
```
