const liveUnitRevision = (book: ScholarBook, target: ScholarSection | TutorSession | ScholarExam, unit: AuditUnit, sourceHash: string): string | undefined => {
  if ("objectives" in target) {
    const section = findSection(book, target.id);
    return section && lessonReviewUnits(section, sourceHash).find(item => item.key === unit.key)?.revision;
